WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY order_date DESC, id) AS row_num FROM orders QUALIFY row_num = 1) SELECT customer_id, DATE_TRUNC('WEEK', order_date) AS week_start, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END), 0), 2) AS discount_per_cancelled, COUNT_IF(status = 'SHIPPED') AS shipped_events, GROUPING(customer_id) AS grouping_id FROM deduped GROUP BY GROUPING SETS ((customer_id, DATE_TRUNC('WEEK', order_date)), (customer_id));
